selection_review=[
 {'pages':[3,4,16],'wording':'any five / any three questions','classification':'exam-level-selection','reason':'All ten questions retained for practice.'},
 {'pages':[6],'wording':'two possible values','classification':'required-answers','reason':'Both tangent constants required in one allocated response, not a choice of one.'},
 {'pages':[14,15],'wording':'arrangements / selected from a panel','classification':'counting-scenario','reason':'Letters and juries are the mathematical data, not student choices of tasks.'},
 {'pages':[24,25],'wording':'multiple choice / 5 possible answers / 5 players','classification':'probability-scenario','reason':'All outcomes and table entries are required within the stated probability tasks. No finite exam-choice pool.'},
]
def classify(c):
 t=c['context'].lower()
 if 'questions' in t and 'any' in t:return ('exam-level-selection','All ten questions retained.')
 if 'one of the circles' in t:return ('diagram-reference','Circle k identifies the required object in the diagram, not a choice.')
 if '5 possible answers' in t or 'multiple choice' in t or 'randomly selects' in t or 'candidates must answer all' in t:return ('probability-scenario','The test is data for one expected-value calculation, not a candidate choice pool.')
 return None
if __name__=='__main__':p.write(selection_review,classify)
